import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, Link } from "react-router-dom"; // 👈 import useParams
import "../styles/main.css";

export default function ViewAdmission() {
  const { id } = useParams(); // 👈 get id from route URL
  const [data, setData] = useState(null);

  useEffect(() => {
    const fetchDetails = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get(`http://localhost:5000/api/admin/admissions/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log("Photo path:", res.data.photo); // 👈 add this line
        setData(res.data);
      } catch (err) {
        console.error("Error fetching admission:", err);
      }
    };
    if (id) fetchDetails();
  }, [id]);

  if (!data) return <p>Loading...</p>;

  return (
    <div className="view-admission">
      <h2>Admission Details</h2>
      {data.photo && (
        
        <img src={`http://localhost:5000${data.photo}`} alt="Student" width="150" />
        
      )}
      <div className="info">
        <p><strong>Admission No:</strong> {data.admissionNo}</p>
        <p><strong>Name:</strong> {data.studentName}</p>
        <p><strong>Parent Name:</strong> {data.parentName}</p>
        <p><strong>Class:</strong> {data.classApplied}</p>
        <p><strong>Age:</strong> {data.age}</p>
        <p><strong>Phone:</strong> {data.phone}</p>
        <p><strong>Email:</strong> {data.email}</p>
        <p><strong>Address:</strong> {data.address}</p>
      </div>
      <Link to="/admin/dashboard" className="back-btn">Back to List</Link>
    </div>
  );
}
